    cx.keystroke_observers.clone().retain(&(), move |callback| {
        (callback)(
            &KeystrokeEvent {
                keystroke: key_down_event.keystroke.clone(),
                action: action.as_ref().map(|action| action.boxed_clone()),
                context_stack: context_stack.clone(),
            },
            self,
            cx,
        )
    });
}

